CREATE TABLE `tblmodulo` (
  `idModulo` int NOT NULL AUTO_INCREMENT,
  `nombreModulo` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `descripcionModulo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`idModulo`),
  UNIQUE KEY `uqNombreModulo` (`nombreModulo`)
) ENGINE=InnoDB AUTO_INCREMENT=10001 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `tblmodulo` VALUES (1,'Producción','Módulo de control de producción de embutidos',1,'2026-09-17 20:07:07','2026-09-17 20:07:07'),(2,'Inventario','Módulo de control de materia prima y producto terminado',1,'2026-09-17 20:07:07','2026-09-20 11:29:01'),(4,'Seguridad','Módulo de administración y seguridad del sistema',1,'2026-09-17 20:07:07','2026-09-17 20:07:07'),(13,'Pruebas','Esto es una prueba controlada por parte de Seguridad.',1,'2026-09-24 05:44:26','2026-09-24 05:44:26'),(6000,'Compras y Cuentas por Pagar','Gestión de compras y cuentas por pagar',1,'2026-11-15 01:22:40','2026-11-15 01:22:40'),(7000,'Ventas','Módulo de ventas: clientes, vendedores, listas de precio, cotizaciones, pedidos, facturación, cuentas por cobrar, recibos, depósitos, comisiones y cierres',1,'2026-09-17 20:07:07','2026-11-15 01:22:40'),(8000,'Bancos','Modulo bancario del sistema de Enbutidos S.A.',1,'2026-11-15 01:22:40','2026-11-15 01:22:40'),(9000,'Recursos Humanos','Módulo de administración del personal: empleados, asistencia, permisos, capacitaciones, desempeño, nómina y liquidaciones',1,'2026-11-15 01:22:40','2026-11-15 01:22:40'),(10000,'Contabilidad','Módulo de Contabilidad',1,'2026-11-15 01:22:40','2026-11-15 01:22:40');
DROP TABLE IF EXISTS `tblmodulocontable`;
CREATE TABLE `tblmodulocontable` (
  `idModuloContable` int NOT NULL AUTO_INCREMENT,
  `nombreModuloContable` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `codigoModuloContable` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `metodoActualizacionModuloContable` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'BATCH',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`idModuloContable`),
  UNIQUE KEY `uqModuloNombre` (`nombreModuloContable`),
  UNIQUE KEY `uqModuloCodigo` (`codigoModuloContable`),
  CONSTRAINT `ckModuloMetodoActualizacion` CHECK ((`metodoActualizacionModuloContable` in (_utf8mb4'LINEA',_utf8mb4'BATCH')))
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `tblmodulocontable` VALUES (1,'Contabilidad','MOD-CONTA','BATCH',1,'2026-11-15 01:22:39','2026-11-15 01:22:39'),(2,'Logística','MOD-LOGIS','BATCH',1,'2026-11-15 01:22:39','2026-11-15 01:22:39'),(3,'Compras','MOD-COMPR','BATCH',1,'2026-11-15 01:22:39','2026-11-15 01:22:39'),(4,'Recursos Humanos','MOD-RRHH','BATCH',1,'2026-11-15 01:22:39','2026-11-15 01:22:39'),(5,'Ventas','MOD-VENTA','BATCH',1,'2026-11-15 01:22:39','2026-11-15 01:22:39'),(6,'Bancos','MOD-BANCO','BATCH',1,'2026-11-15 01:22:39','2026-11-15 01:22:39');
DROP TABLE IF EXISTS `tblmodulocuentapais`;
CREATE TABLE `tblmodulocuentapais` (
  `idModuloContable` int NOT NULL,
  `idCuenta` int NOT NULL,
  `idPais` int NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`idModuloContable`,`idCuenta`,`idPais`),
  KEY `idxModuloCuentaPaisCuenta` (`idCuenta`),
  KEY `idxModuloCuentaPaisPais` (`idPais`),
  CONSTRAINT `Fk_ModuloCuentaPais_Cuenta` FOREIGN KEY (`idCuenta`) REFERENCES `tblcuenta` (`idCuenta`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `Fk_ModuloCuentaPais_Modulo` FOREIGN KEY (`idModuloContable`) REFERENCES `tblmodulocontable` (`idModuloContable`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `Fk_ModuloCuentaPais_Pais` FOREIGN KEY (`idPais`) REFERENCES `tblpais` (`idPais`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
